fn digits(v:[*]const i64,a:usize,b:usize,out:*i64)bool{var x:i64=0;for(a..b)|i|{if(v[i]<48 or v[i]>57)return false;x=x*10+v[i]-48;}out.*=x;return true;}
export fn parse_date(v:[*c]const i64,n:usize)i64{if(v==null or n<9 or n>11 or v[0]<8 or v[0]>10 or n!=@as(usize,@intCast(v[0]))+1)return -1;const len:usize=@intCast(v[0]);var s1:usize=0;var s2:usize=0;for(1..len+1)|i|{if(v[i]<0 or v[i]>127)return -1;if(v[i]==47){if(s1==0)s1=i else if(s2==0)s2=i else return -1;}}if(s1<2 or s1>3 or s2<=s1+1 or s2-s1<2 or s2-s1>3 or len-s2!=4)return -1;var d:i64=0;var m:i64=0;var y:i64=0;if(!digits(v,1,s1,&d)||!digits(v,s1+1,s2,&m)||!digits(v,s2+1,len+1,&y)||m<1 or m>12)return -1;var days=[_]i64{31,28,31,30,31,30,31,31,30,31,30,31};if(m==2 and y%4==0 and (y%100!=0 or y%400==0))days[1]=29;if(d<1 or d>days[@intCast(m-1)])return -1;return y*10000+m*100+d;}
